func summarizeOverrides(r model.Record) string {
	if len(r.VLANOverrides) == 0 {
		return "—"
	}
	out := ""
	for i, o := range r.VLANOverrides {
		if i > 0 {
			out += ", "
		}
		switch {
		case o.NXDomain:
			out += o.VLAN + ": ✗"
		case o.Value != "":
			out += o.VLAN + ": " + o.Value
		default:
			out += o.VLAN + ": (dflt)"
		}
	}
	return out
}

